const fs = require('fs');
const path = require('path');
const { withAppBuildGradle, withDangerousMod } = require('@expo/config-plugins');

const MARKER = 'oslyn-upload-signing';

const GITIGNORE_BLOCK = `
# Upload signing and Play Console credentials.
# debug.keystore is generated by Expo and stays committed.
*.keystore
!debug.keystore
keystore.properties
play-store-key.json
`;

function matchingBrace(contents, openIndex) {
  let depth = 0;
  for (let i = openIndex; i < contents.length; i += 1) {
    const ch = contents[i];
    if (ch === '{') depth += 1;
    else if (ch === '}') {
      depth -= 1;
      if (depth === 0) return i;
    }
  }
  return -1;
}

function signingHelper(versionCodeFallback) {
  return `
// ${MARKER}
// Release uploads use the Play upload key when OSLYN_UPLOAD_* is set
// (android/keystore.properties, Gradle properties, or the environment).
// Local release builds fall back to the debug keystore so \`yarn android\` still works.
def oslynKeystoreProperties = new Properties()
def oslynKeystorePropertiesFile = rootProject.file("keystore.properties")
if (oslynKeystorePropertiesFile.exists()) {
    oslynKeystorePropertiesFile.withInputStream { stream -> oslynKeystoreProperties.load(stream) }
}

def oslynUploadValue = { String name ->
    def fromFile = oslynKeystoreProperties.getProperty(name)
    if (fromFile != null && !fromFile.trim().isEmpty()) {
        return fromFile.trim()
    }
    def fromGradle = findProperty(name)
    if (fromGradle != null && !fromGradle.toString().trim().isEmpty()) {
        return fromGradle.toString().trim()
    }
    def fromEnv = System.getenv(name)
    if (fromEnv != null && !fromEnv.trim().isEmpty()) {
        return fromEnv.trim()
    }
    return null
}

def oslynUploadStoreFile = oslynUploadValue("OSLYN_UPLOAD_STORE_FILE")
def oslynUploadStorePassword = oslynUploadValue("OSLYN_UPLOAD_STORE_PASSWORD")
def oslynUploadKeyAlias = oslynUploadValue("OSLYN_UPLOAD_KEY_ALIAS")
def oslynUploadKeyPassword = oslynUploadValue("OSLYN_UPLOAD_KEY_PASSWORD")
def oslynHasUploadSigning = oslynUploadStoreFile && oslynUploadStorePassword && oslynUploadKeyAlias && oslynUploadKeyPassword
def oslynVersionCode = (findProperty("OSLYN_VERSION_CODE") ?: System.getenv("OSLYN_VERSION_CODE") ?: "${versionCodeFallback}").toString().toInteger()

`;
}

function insertBeforeAndroidBlock(contents, helper) {
  const match = contents.match(/^android\s*\{/m);
  if (!match) {
    throw new Error('withAndroidReleaseSigning: android block not found in app/build.gradle');
  }
  return contents.slice(0, match.index) + helper + contents.slice(match.index);
}

function insertReleaseSigningConfig(contents) {
  const start = contents.search(/signingConfigs\s*\{/);
  if (start < 0) {
    throw new Error('withAndroidReleaseSigning: signingConfigs block not found in app/build.gradle');
  }
  const open = contents.indexOf('{', start);
  const close = matchingBrace(contents, open);
  if (close < 0) {
    throw new Error('withAndroidReleaseSigning: signingConfigs block is unbalanced');
  }
  let insertAt = close;
  while (insertAt > 0 && (contents[insertAt - 1] === ' ' || contents[insertAt - 1] === '\t')) {
    insertAt -= 1;
  }
  const releaseBlock = `        release {
            if (oslynHasUploadSigning) {
                def resolvedStore = new File(oslynUploadStoreFile)
                storeFile resolvedStore.isAbsolute() ? resolvedStore : rootProject.file(oslynUploadStoreFile)
                storePassword oslynUploadStorePassword
                keyAlias oslynUploadKeyAlias
                keyPassword oslynUploadKeyPassword
            }
        }
    }`;
  return contents.slice(0, insertAt) + releaseBlock + contents.slice(close + 1);
}

function pointReleaseBuildTypeAtUploadKey(contents) {
  const buildTypes = contents.search(/buildTypes\s*\{/);
  if (buildTypes < 0) {
    throw new Error('withAndroidReleaseSigning: buildTypes block not found in app/build.gradle');
  }
  const releaseIdx = contents.indexOf('release {', buildTypes);
  if (releaseIdx < 0) {
    throw new Error('withAndroidReleaseSigning: release build type not found in app/build.gradle');
  }
  const needle = 'signingConfig signingConfigs.debug';
  const signingIdx = contents.indexOf(needle, releaseIdx);
  if (signingIdx < 0) {
    throw new Error('withAndroidReleaseSigning: release signingConfig not found in app/build.gradle');
  }
  const replacement = 'signingConfig oslynHasUploadSigning ? signingConfigs.release : signingConfigs.debug';
  return contents.slice(0, signingIdx) + replacement + contents.slice(signingIdx + needle.length);
}

function makeVersionCodeOverridable(contents) {
  const numeric = contents.match(/versionCode\s+(\d+)/);
  if (numeric) {
    contents = contents.replace(
      /def oslynVersionCode = \(findProperty\("OSLYN_VERSION_CODE"\) \?: System\.getenv\("OSLYN_VERSION_CODE"\) \?: "\d+"\)/,
      `def oslynVersionCode = (findProperty("OSLYN_VERSION_CODE") ?: System.getenv("OSLYN_VERSION_CODE") ?: "${numeric[1]}")`
    );
  }
  if (/versionCode oslynVersionCode\b/.test(contents)) {
    return contents;
  }
  if (!numeric) {
    throw new Error('withAndroidReleaseSigning: versionCode assignment not found in app/build.gradle');
  }
  return contents.replace(/versionCode\s+\d+/, 'versionCode oslynVersionCode');
}

function applyReleaseSigning(contents) {
  let next = contents;
  if (!next.includes(MARKER)) {
    const versionMatch = next.match(/versionCode\s+(\d+)/);
    const fallback = versionMatch ? versionMatch[1] : '1';
    next = insertBeforeAndroidBlock(next, signingHelper(fallback));
    next = insertReleaseSigningConfig(next);
    next = pointReleaseBuildTypeAtUploadKey(next);
  }
  next = makeVersionCodeOverridable(next);
  return next;
}

function ensureGitignore(androidRoot) {
  const gitignorePath = path.join(androidRoot, '.gitignore');
  let contents = fs.existsSync(gitignorePath) ? fs.readFileSync(gitignorePath, 'utf8') : '';
  if (contents.includes('keystore.properties') && contents.includes('play-store-key.json')) {
    return;
  }
  if (contents.length && !contents.endsWith('\n')) {
    contents += '\n';
  }
  fs.writeFileSync(gitignorePath, contents + GITIGNORE_BLOCK);
}

function copyFastlaneAssets(androidRoot) {
  const sourceDir = path.join(__dirname, '..', 'fastlane_assets', 'android');
  if (!fs.existsSync(sourceDir)) {
    return;
  }
  const destDir = path.join(androidRoot, 'fastlane');
  fs.mkdirSync(destDir, { recursive: true });
  for (const name of fs.readdirSync(sourceDir)) {
    const from = path.join(sourceDir, name);
    if (!fs.statSync(from).isFile()) continue;
    fs.copyFileSync(from, path.join(destDir, name));
  }
}

function withAndroidReleaseSigning(config) {
  config = withAppBuildGradle(config, (mod) => {
    if (mod.modResults.language !== 'groovy') {
      throw new Error('withAndroidReleaseSigning only supports Groovy app/build.gradle');
    }
    mod.modResults.contents = applyReleaseSigning(mod.modResults.contents);
    return mod;
  });

  config = withDangerousMod(config, [
    'android',
    (mod) => {
      const androidRoot = mod.modRequest.platformProjectRoot;
      ensureGitignore(androidRoot);
      copyFastlaneAssets(androidRoot);
      return mod;
    },
  ]);

  return config;
}

module.exports = withAndroidReleaseSigning;
